body.script:
function cosVisaChange(v){
    document.getElementById('cos_cancelled_docs').style.display = v==='cancelled' ? 'block' : 'none';
    document.getElementById('cos_valid_docs').style.display = v==='valid' ? 'block' : 'none';
}
function cosFileSelected(input, key){
    if(input.files && input.files[0]){
        var el = document.getElementById('uploaded_'+key);
        el.style.display = 'flex';
        document.getElementById('name_'+key).textContent = input.files[0].name;
        document.getElementById('box_'+key).style.borderColor = '#1abc9c';
    }
}
function cosRemoveFile(key){
    document.getElementById('uploaded_'+key).style.display = 'none';
    document.getElementById('box_'+key).style.borderColor = '#1a2340';
    var inputs = document.getElementById('box_'+key).querySelectorAll('input[type=file]');
    inputs.forEach(function(i){i.value='';});
}
(function(){
    var vs = document.querySelector('input[name=visa_status]:checked');
    if(vs) cosVisaChange(vs.value);
})();
